OpenAPI 3.0 specification, using fastmcp's OpenAPI integration.

Requires: fastmcp==3.4.4, httpx
"""

import asyncio

import httpx
from fastmcp import FastMCP

# --- Minimal OpenAPI 3.0 specification (as a Python dict) -----------------
OPENAPI_SPEC = {
    "openapi": "3.0.0",
    "info": {"title": "Example API", "version": "1.0.0"},
    "paths": {
        "/items": {
            "get": {
                "operationId": "list_items",
                "summary": "List all items",
                "responses": {
                    "200": {
                        "description": "A list of items",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "type": "array",
                                    "items": {"type": "object"},
                                }
                            }
                        },
                    }
                },
            },
            "post": {
                "operationId": "create_item",
                "summary": "Create a new item",
                "requestBody": {
                    "required": True,
                    "content": {
                        "application/json": {
                            "schema": {
                                "type": "object",
                                "properties": {
                                    "name": {"type": "string"},
                                },
                                "required": ["name"],
                            }
                        }
                    },
                },
                "responses": {
                    "201": {
                        "description": "Item created",
                        "content": {
                            "application/json": {
                                "schema": {"type": "object"}
                            }
                        },
                    }
                },
            },
        },
        "/items/{item_id}": {
            "get": {
                "operationId": "get_item",
                "summary": "Get a single item by ID",
                "parameters": [
                    {
                        "name": "item_id",
                        "in": "path",
                        "required": True,
                        "schema": {"type": "integer"},
                    }
                ],
                "responses": {
                    "200": {
                        "description": "The requested item",
                        "content": {
                            "application/json": {
                                "schema": {"type": "object"}
                            }
                        },
                    }
                },
            }
        },
    },
}


def build_mcp_server(
    openapi_spec: dict,
    client: httpx.AsyncClient,
    name: str = "OpenAPI MCP Server",
) -> FastMCP:
    """Build a FastMCP server whose tools mirror the given OpenAPI spec.

    Args:
        openapi_spec: A minimal OpenAPI 3.0 specification as a dict.
        client: An httpx.AsyncClient already configured with the API base URL.
        name: Name to give the generated MCP server.

    Returns:
        A FastMCP server instance with tools generated from the spec.
    """
    return FastMCP.from_openapi(
        openapi_spec=openapi_spec,
        client=client,
        name=name,
    )


async def main() -> None:
    async with httpx.AsyncClient(base_url="https://api.example.com") as client:
        mcp = build_mcp_server(OPENAPI_SPEC, client)
        await mcp.run_async()


if __name__ == "__main__":
    asyncio.run(main())

